'use strict';

// MAIN //

/**
* Applies a one-dimensional strided array function to a list of specified dimensions in three input ndarrays and assigns results to a provided output ndarray.
*
* ## Notes
*
* -   The `views`, `shape`, `stridesX`, `stridesY`, `stridesZ`, and `stridesW` parameters are unused. Providing empty arrays for these parameters is recommended in order to ensure a monomorphic API.
*
* @private
* @param {Function} fcn - wrapper for a one-dimensional strided array function
* @param {Array<Object>} arrays - ndarray descriptors
* @param {Array<Object>} views - initialized ndarray descriptors representing subarray views
* @param {Array<integer>} shape - loop dimensions
* @param {Array<integer>} stridesX - loop dimension strides for the first input ndarray
* @param {Array<integer>} stridesY - loop dimension strides for the second input ndarray
* @param {Array<integer>} stridesZ - loop dimension strides for the third input ndarray
* @param {Array<integer>} stridesW - loop dimension strides for the output ndarray
* @param {Object} strategyX - strategy for marshaling data to and from a first input ndarray view
* @param {Object} strategyY - strategy for marshaling data to and from a second input ndarray view
* @param {Object} strategyZ - strategy for marshaling data to and from a third input ndarray view
* @param {Object} strategyW - strategy for marshaling data to and from an output ndarray view
* @param {Options} opts - function options
* @returns {void}
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var ndarray2array = require( '@stdlib/ndarray/base/to-array' );
* var gwhere = require( '@stdlib/blas/ext/base/ndarray/gwhere' );
* var strategy = require( '@stdlib/ndarray/base/kernels/generic/unary-strided1d/strategy' );
*
* // Create data buffers:
* var xbuf = new Float64Array( [ 1.0, 0.0, 1.0, 0.0 ] );
* var ybuf = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );
* var zbuf = new Float64Array( [ -1.0, -2.0, -3.0, -4.0 ] );
* var wbuf = new Float64Array( [ 0.0, 0.0, 0.0, 0.0 ] );
*
* // Define the array shapes:
* var xsh = [ 2, 2 ];
* var ysh = [ 2, 2 ];
* var zsh = [ 2, 2 ];
* var wsh = [ 2, 2 ];
*
* // Define the array strides:
* var sx = [ 2, 1 ];
* var sy = [ 2, 1 ];
* var sz = [ 2, 1 ];
* var sw = [ 2, 1 ];
*
* // Define the index offsets:
* var ox = 0;
* var oy = 0;
* var oz = 0;
* var ow = 0;
*
* // Create the input ndarray descriptors:
* var x = {
*     'dtype': 'float64',
*     'data': xbuf,
*     'shape': xsh,
*     'strides': sx,
*     'offset': ox,
*     'order': 'row-major'
* };
*
* var y = {
*     'dtype': 'float64',
*     'data': ybuf,
*     'shape': ysh,
*     'strides': sy,
*     'offset': oy,
*     'order': 'row-major'
* };
*
* var z = {
*     'dtype': 'float64',
*     'data': zbuf,
*     'shape': zsh,
*     'strides': sz,
*     'offset': oz,
*     'order': 'row-major'
* };
*
* // Create an output ndarray descriptor:
* var w = {
*     'dtype': 'float64',
*     'data': wbuf,
*     'shape': wsh,
*     'strides': sw,
*     'offset': ow,
*     'order': 'row-major'
* };
*
* // Define input/output strategies for iterating over subarray views:
* var strategyX = strategy( x );
* var strategyY = strategy( y );
* var strategyZ = strategy( z );
* var strategyW = strategy( w );
*
* // Apply strided function:
* kernel( gwhere, [ x, y, z, w ], [], [], [], [], [], [], strategyX, strategyY, strategyZ, strategyW, {} );
*
* var v = w.data;
* // returns <Float64Array>[ 1.0, -2.0, 3.0, -4.0 ]
*/
function kernel( fcn, arrays, views, shape, stridesX, stridesY, stridesZ, stridesW, strategyX, strategyY, strategyZ, strategyW, opts ) { // eslint-disable-line max-len, max-params
	arrays[ 0 ] = strategyX.input( arrays[ 0 ] );
	arrays[ 1 ] = strategyY.input( arrays[ 1 ] );
	arrays[ 2 ] = strategyZ.input( arrays[ 2 ] );
	arrays[ 3 ] = strategyW.input( arrays[ 3 ] );
	fcn( arrays, opts );
	strategyW.output( arrays[ 3 ] );
}


// EXPORTS //

module.exports = kernel;
